// Meme swarms: is one picture being pushed by a swarm (bot network, astroturfing, brigading)?
// The types mirror swarm/model.py field for field (that file is the contract: change both together).
// Below them, the pure logic the UI draws from (dot layout, chips, labels: tested in
// tests/test_trackdown_swarm.mjs) and the two reads of the API. Nothing here touches the DOM.

export type SwarmPlatform = "bluesky" | "x" | "web";
export type SwarmFamily = "timing" | "accounts" | "copy" | "boost";
/** swarm -> "Shill", organic -> "Chill", unclear -> "Can't tell": about the group of posts, never one account */
export type SwarmVerdict = "swarm" | "organic" | "unclear";
export type SwarmBasis = "live" | "sample";
export type SwarmAction = "post" | "repost" | "quote" | "reply" | "like";

export interface SwarmSignal {
  family: SwarmFamily;
  name: string;
  score: number; // 0..1
  polarity: "for" | "against";
  /** a few plain words with the numbers, shown as is: "31 accounts in 4 min" */
  summary: string;
  numbers: Record<string, number | string | null>;
  examples: string[];
}

export interface SwarmBurst { start: string; end: string; n_posts: number; n_accounts: number }

export interface SwarmTimelinePoint {
  t: number; // epoch seconds
  a: number; // account index within the report; not a name
  k: SwarmAction;
  g: number; // same-words group; 0 = own words
  burst: boolean;
}

export interface SwarmReport {
  verdict: SwarmVerdict;
  why_unclear: string;
  score: number;
  guard: number;
  p_value: number | null;
  families: Partial<Record<SwarmFamily, number>>;
  fired: SwarmFamily[];
  signals: SwarmSignal[]; // strongest first, guards last
  n_posts: number;
  n_boosts: number;
  n_accounts: number;
  n_accounts_known: number;
  first_at: string | null;
  last_at: string | null;
  burst: SwarmBurst | null;
  timeline: SwarmTimelinePoint[]; // <= 300, time order
  basis: SwarmBasis;
  basis_note: string;
  version: string;
}

export interface SwarmPost { url: string; platform: SwarmPlatform; handle: string | null; at: string | null; text: string }

export interface SwarmCard {
  id: string;
  thumb: string;
  verdict: SwarmVerdict;
  score: number;
  n_posts: number;
  n_accounts: number;
  first_at: string | null;
  last_at: string | null;
  families: Partial<Record<SwarmFamily, number>>;
  headline: string;
  kind: string | null;
}

export interface SwarmDetail extends SwarmCard {
  picture: string;
  report: SwarmReport;
  posts: SwarmPost[]; // <= 30, earliest first
  caption: string | null;
}

export interface SwarmWall { items: SwarmCard[]; as_of: string | null; window_h: number | null }

/** The swarm page's Back control: "history" when the app opened the page over one of its own
 *  screens (a wall tile, "Live on Bluesky": main.ts pushes `{ swarm, inApp: true }`), so the
 *  browser's Back restores that screen exactly; "home" when it was opened from a link. */
export function swarmBackTarget(state: unknown): "history" | "home" {
  return !!state && typeof state === "object" && (state as { inApp?: unknown }).inApp === true ? "history" : "home";
}

/** a lookup's pointer to the live Bluesky group of the same picture (its page is ?swarm=<id>) */
export interface SwarmLiveRef { id: string; verdict: SwarmVerdict; n_accounts: number }

// ---------------------------------------------------------------- words and colours

export const VERDICT: Record<SwarmVerdict, { word: string; css: string }> = {
  swarm: { word: "Shill", css: "var(--shill)" },
  organic: { word: "Chill", css: "var(--chill)" },
  unclear: { word: "Can't tell", css: "var(--unsure)" },
};
export const FAMILY_NAME: Record<SwarmFamily, string> = { timing: "Timing", accounts: "Accounts", copy: "Copy-paste", boost: "Boosting" };

/** fills for same-words groups, largest group first (the painting's other colours, none of the verdict ones) */
export const GROUP_FILLS = ["#e4b36a", "#7aa2f0", "#b9a6e3", "#f2efe9"];

export interface SwarmChip { family: SwarmFamily; label: string; summary: string; score: number }

/** What the verdict rests on, as at most `max` chips. Shill: the strongest "for" signal of each
"""The meme swarm contract: what goes into the scorer and the report that comes out.

A *meme* here is one picture and the posts that carry it. The scorer asks one question about
that set of posts: do the accounts behind them act like a swarm (bot network, astroturfing,
brigading) or like people who each found the picture funny? It never judges a single post or a
single account, and a picture being popular is not evidence: the signals are about *how* it was
posted (timing, how alike the accounts are, reused words and files, who boosts whom).

These models are the JSON served by the API and read by Trackdown. Change a field only together
with web/trackdown/src/data/swarm.ts.
"""

from __future__ import annotations

from datetime import datetime
from typing import Literal

from pydantic import BaseModel, Field

Platform = Literal["bluesky", "x", "web"]
Family = Literal["timing", "accounts", "copy", "boost"]
# swarm -> "Shill", organic -> "Chill", unclear -> "Can't tell". A verdict describes the group of
# posts, never one account.
Verdict = Literal["swarm", "organic", "unclear"]
# live: every post of this picture our Bluesky firehose saw in the window (complete for the
# window). sample: what a search returned for a lookup (a sample; copies are missing).
Basis = Literal["live", "sample"]

FAMILIES: tuple[Family, ...] = ("timing", "accounts", "copy", "boost")


class Sighting(BaseModel):
    """One action that carries or boosts the picture."""

    id: str  # post uri / "x:<id>" / page url: unique within the meme
    platform: Platform
    account: str  # stable account key: did, or "x:<handle lowercased>"
    at: datetime | None = None
    # False when `at` is a search-engine hint or a crawl date: left out of timing signals
    time_exact: bool = True
    # post: the account posted the picture itself. repost/quote/reply/like: it boosted `target`.
    kind: Literal["post", "repost", "quote", "reply", "like"] = "post"
    target: str | None = None  # the Sighting.id that was boosted (kind != "post")
    text: str = ""  # the words posted with the picture
    url: str | None = None
    # the exact file: Bluesky blob CID or X media key. Equal keys = the same upload bytes.
    media_key: str | None = None
    langs: list[str] = Field(default_factory=list)
    # public counts on the post, when the platform shows them
    likes: int | None = None
    reposts: int | None = None
    replies: int | None = None


class AccountInfo(BaseModel):
    """What is known about an account. Every field may be missing: a signal that needs a field
    counts only the accounts that have it and says how many that was."""

    key: str  # Sighting.account
    platform: Platform = "bluesky"
    handle: str | None = None
    name: str | None = None
    created_at: datetime | None = None
    followers: int | None = None
    following: int | None = None
    posts_count: int | None = None
    bio: str | None = None
    has_avatar: bool | None = None
    host: str | None = None  # Bluesky PDS host


class SwarmSignal(BaseModel):
    family: Family
    name: str  # snake_case, stable: "burst", "same_text", ...
    score: float  # 0..1
    # for: points to a swarm. against: points to ordinary people (an organic guard).
    polarity: Literal["for", "against"] = "for"
    # a few plain words with the numbers, shown as a chip: "31 accounts in 4 min"
    summary: str
    numbers: dict[str, float | int | str | None] = Field(default_factory=dict)
    # Sighting ids that show it (<= 12), for links. Only timing and copy signals that point to a
    # swarm carry them: accounts and boost examples would single out accounts.
    examples: list[str] = Field(default_factory=list)


class Burst(BaseModel):
    """The densest stretch of posting."""

    start: datetime
    end: datetime
    n_posts: int
    n_accounts: int


class TimelinePoint(BaseModel):
    """One sighting for the dot timeline (<= 300, evenly sampled, in time order)."""

    t: float  # epoch seconds
    a: int  # index of the account within this report (0 = first to post); not a name
    k: Literal["post", "repost", "quote", "reply", "like"] = "post"
    # posts with the same number share the same words (0 = own words or no words)
    g: int = 0
    burst: bool = False


class SwarmReport(BaseModel):
    verdict: Verdict = "unclear"
    # why it is unclear, in a few words ("only 3 accounts"); empty otherwise
    why_unclear: str = ""
    score: float = 0.0  # 0..1, noisy-OR of the two strongest families
    guard: float = 0.0  # 0..1, strongest organic guard
    p_value: float | None = None  # the timing test, when it ran
    families: dict[Family, float] = Field(default_factory=dict)
    fired: list[Family] = Field(default_factory=list)
    signals: list[SwarmSignal] = Field(default_factory=list)  # strongest first, guards last
    n_posts: int = 0  # sightings of kind "post"
    n_boosts: int = 0  # the other kinds
    n_accounts: int = 0  # distinct accounts that posted the picture
    n_accounts_known: int = 0  # of those, with any AccountInfo
    first_at: datetime | None = None
    last_at: datetime | None = None
    burst: Burst | None = None
    timeline: list[TimelinePoint] = Field(default_factory=list)
    basis: Basis = "sample"
    # one short line on what the data covers: "43 posts our Bluesky feed saw in 24 h"
    basis_note: str = ""
    version: str = ""


class SwarmPost(BaseModel):
    """A post shown under a swarm (a link, never a label on its author)."""

    url: str
    platform: Platform = "bluesky"
    handle: str | None = None
    at: datetime | None = None
    text: str = ""


class SwarmCard(BaseModel):
    """One picture on the wall (GET /api/swarms)."""

    id: str  # stable id of the picture group
    thumb: str  # https image URL, safe to hotlink
    verdict: Verdict
    score: float
    n_posts: int
    n_accounts: int
    first_at: datetime | None = None
    last_at: datetime | None = None
    families: dict[Family, float] = Field(default_factory=dict)
    # the strongest signal's summary: "43 accounts · same words"
    headline: str = ""
    # what the picture is, when read: meme, ad, photo, screenshot, other
    kind: str | None = None


class SwarmDetail(SwarmCard):
    """GET /api/swarms/{id}."""

    picture: str  # full-size image URL
    report: SwarmReport
    posts: list[SwarmPost] = Field(default_factory=list)  # <= 30, earliest first
    caption: str | None = None  # the text on the picture, when read


class SwarmLiveRef(BaseModel):
    """A pointer from a lookup to the live Bluesky group of the same picture (its page is
    /?swarm=<id>, its data GET /api/swarms/{id}). Small on purpose: lookups are polled."""

    id: str
    verdict: Verdict
    n_accounts: int


class SwarmWall(BaseModel):
    items: list[SwarmCard] = Field(default_factory=list)
    as_of: datetime | None = None
    window_h: float | None = None
def score_swarm(
    sightings: list[Sighting],
    accounts: dict[str, AccountInfo] | None = None,  # keyed by Sighting.account
    *,
    basis: Basis = "sample",
    basis_note: str = "",
    baseline: Baseline | None = None,
    selected_by_file: bool = False,
    window: tuple[datetime, datetime] | None = None,
    cfg: SwarmConfig = SwarmConfig(),  # noqa: B008  (frozen dataclass: safe as a default)
) -> SwarmReport:
    """Score one picture's sightings.

    selected_by_file: the caller picked this group because one exact file was posted by many
    accounts; that file is then the selection rule, so same_file and own_files are not computed.
    window: the stretch the caller watched completely (the live pass window). Timing null worlds
    stay inside [first post, window end]; without it, inside [first post, last post], so a sample
    of the newest posts cannot show a significant burst."""
    info = dict(accounts or {})
    ordered = _dedupe(sightings)
    tmap: dict[str, float | None] = {s.id: _ts(s.at) for s in ordered}

    posts: list[_Post] = []
    boosts: list[Sighting] = []
    for s in ordered:
        if s.kind != "post":
            boosts.append(s)
            continue
        norm, words = _norm_words(s.text)
        posts.append(
            _Post(
                id=s.id,
                account=s.account,
                platform=s.platform,
                t=tmap[s.id] if s.time_exact else None,
                t_any=tmap[s.id],
                norm=norm,
                words=words,
                media_key=s.media_key or None,
                likes=s.likes,
                reposts=s.reposts,
                replies=s.replies,
            )
        )

    first_post: dict[str, tuple] = {}
    posts_by_account: dict[str, list[_Post]] = defaultdict(list)
    for p in posts:
        posts_by_account[p.account].append(p)
        key = (p.t is None, p.t if p.t is not None else (p.t_any or 0.0), p.id)
        if p.account not in first_post or key < first_post[p.account]:
            first_post[p.account] = key
    accs = sorted(first_post, key=lambda a: (*first_post[a], a))

    exact = [t for s in ordered if s.time_exact and (t := tmap[s.id]) is not None]
    anyt = [t for s in ordered if (t := tmap[s.id]) is not None]
    times = exact or anyt
    first_at = _dt(min(times)) if times else None
    last_at = _dt(max(times)) if times else None
    ref_t: dict[str, float] = {}
    for a in accs:
        ts = [p.t_any for p in posts_by_account[a] if p.t_any is not None]
        if ts:
            ref_t[a] = min(ts)
        elif anyt:
            ref_t[a] = max(anyt)
    post_times = [p.t_any for p in posts if p.t_any is not None]

    ctx = _Ctx(
        cfg=cfg,
        posts=posts,
        boosts=boosts,
        accounts=accs,
        posts_by_account=dict(posts_by_account),
        info=info,
        ref_t=ref_t,
        rng=np.random.default_rng(_seed(cfg, ordered)),
        first_t=min(post_times) if post_times else None,
        window_end=_ts(window[1]) if window else None,
        selected_by_file=selected_by_file,
    )
    report = SwarmReport(
        n_posts=len(posts),
        n_boosts=len(boosts),
        n_accounts=len(accs),
        n_accounts_known=sum(1 for a in accs if a in info),
        first_at=first_at,
        last_at=last_at,
        basis=basis,
        basis_note=basis_note,
        version=cfg.version,
        families={f: 0.0 for f in FAMILIES},
    )
    if not accs:
        report.why_unclear = "no posts of the picture"
        report.timeline = _timeline(ctx, ordered, None, False)
        return report

    sigs: list[SwarmSignal] = []
    t_sigs, p_value, burst, t_info = _timing(ctx)
    sigs += t_sigs
    sigs += _accounts(ctx, baseline)
    sigs += _copy(ctx)
    sigs += _boost(ctx)
    fam = {f: max([s.score for s in sigs if s.family == f], default=0.0) for f in FAMILIES}
    guards = _guards(ctx, fam["timing"])
    guards += _publisher(ctx, fam["accounts"])

    fired = [f for f in FAMILIES if fam[f] >= cfg.family_fire]
    top2 = sorted(fam.values(), reverse=True)[:2]
    score = 1 - math.prod(1 - s for s in top2)
    guard = max([g.score for g in guards], default=0.0)
    # the p-value of the timing signal that gave the family its score (clockwork has none)
    lead = max(
        (s for s in t_sigs),
        key=lambda s: (s.score, s.numbers.get("p_value") is not None, s.name),
        default=None,
    )
    lead_p = lead.numbers.get("p_value") if lead is not None else None
    timing_p_ok = not ("timing" in fired and len(fired) == cfg.min_families_swarm) or (
        lead_p is not None and lead_p <= cfg.max_p_swarm
    )
    # without a window, posts inside a few minutes say nothing about how the picture spread
    short = (
        window is None
        and t_info["timed_accounts"] >= cfg.min_burst_accounts
        and t_info["span_s"] < cfg.organic_min_span_s
    )

    # The one exception to "a guard never overrides a fired family" (review finding 5): accounts
    # that openly carry one name are one publisher (a leisure trust's venue accounts posting the
    # same job advert at 09:00). Its own scheduled, identical posts are what timing and copy show
    # anyway, so they are not evidence of a swarm. Long-standing accounts: organic. Younger ones:
    # unclear, as a franchise's marketing accounts and an ad network look the same. Never when
    # the accounts family fired (minted handles, a fresh cohort, copied bios).
    pub = next((g for g in guards if g.name == "one_publisher"), None)
    publisher = pub is not None and pub.score >= cfg.guard_strong and "accounts" not in fired

    if len(accs) < cfg.min_accounts:
        verdict, why = "unclear", f"only {_accounts_word(len(accs))}"
    elif publisher:
        if pub.numbers.get("established"):
            verdict, why = "organic", ""
        else:
            verdict, why = "unclear", "one name, new accounts"
    elif (
        len(fired) >= cfg.min_families_swarm
        and score >= cfg.min_score_swarm
        and guard < cfg.guard_strong
        and timing_p_ok
    ):
        verdict, why = "swarm", ""
    elif guard >= cfg.guard_strong and not fired and not short:
        verdict, why = "organic", ""
    else:
        verdict, why = "unclear", _why_unclear(fired, guard, timing_p_ok, short, cfg)

    keep = sorted((s for s in sigs if s.score > 0), key=lambda s: (-s.score, s.family, s.name))
    keep += sorted((g for g in guards if g.score > 0), key=lambda s: (-s.score, s.family, s.name))
    burst_fired = any(s.name == "burst" and s.score > 0 for s in sigs)

    report.verdict = verdict
    report.why_unclear = why
    report.score = _r(score)
    report.guard = _r(guard)
    report.p_value = _sig(p_value) if p_value is not None else None
    report.families = {f: _r(fam[f]) for f in FAMILIES}
    report.fired = fired
    report.signals = keep
    report.burst = burst
    report.timeline = _timeline(ctx, ordered, burst, burst_fired)
    return report
/* Meme swarms (ui/swarm.ts): the strip on a meme result, the home wall, the page of one live picture.
   The story's language: hairlines, near-black surfaces, the verdict word in its colour. */

/* the strip: the dots under the picture's column, the answer under the headline's */
.sw { --sw-dot: #8f8b84; display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); grid-template-areas: "plot word" "plot say"; gap: 0 40px; }
.sw-plot { grid-area: plot; align-self: center; margin: 0; min-width: 0; }
.sw-plot svg { display: block; width: 100%; height: auto; max-height: 180px; overflow: visible; }
.sw-band { fill: color-mix(in srgb, var(--vc) 16%, transparent); }
.sw-base { stroke: var(--line-2); stroke-width: 1; vector-effect: non-scaling-stroke; }
.sw-axis { display: flex; justify-content: space-between; gap: 12px; margin-top: 8px; font: 400 11.5px/1.3 var(--mono); color: var(--text-3); }
.sw-say { grid-area: say; min-width: 0; }
.sw .sw-word { grid-area: word; align-self: end; margin: 0; font: 600 clamp(34px, 3.6vw, 46px)/1.02 var(--sans); letter-spacing: -0.03em; color: var(--vc); }
.sw-chips { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0 0; padding: 0; list-style: none; }
.sw-chips li { display: inline-flex; align-items: baseline; gap: 9px; max-width: 100%; padding: 7px 11px; font: 500 14.5px/1.3 var(--sans); color: var(--text); background: var(--surface-2); border: 1px solid var(--line-2); overflow-wrap: anywhere; }
.sw-chips b { flex: none; font: 500 10px/1.3 var(--mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-3); }
.sw-why { margin: 14px 0 0; font: 400 17px/1.4 var(--sans); color: var(--text); overflow-wrap: anywhere; }
.sw-note { margin: 16px 0 0; font: 400 12.5px/1.5 var(--sans); color: var(--text-3); overflow-wrap: anywhere; }
.sw-live { display: inline-flex; align-items: center; min-height: 32px; margin: 6px 0 0; font: 500 13px/1.3 var(--sans); color: var(--text-2); text-decoration: underline; text-decoration-color: var(--line-3); text-underline-offset: 3px; }
.sw-live:hover { color: var(--text); text-decoration-color: var(--text); }
@media (prefers-reduced-motion: no-preference) {
  .sw-plot svg { animation: sw-draw 1.1s var(--ease-out) 0.15s both; }
}
@keyframes sw-draw { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

/* stacked: the strip inside the swarm page's hero column */
.sw.stack { grid-template-columns: minmax(0, 1fr); grid-template-areas: "word" "plot" "say"; margin: 0; padding: 0; border: 0; }
.sw.stack .sw-word { font-size: clamp(38px, 5vw, 64px); }
.sw.stack .sw-plot, .sw.stack .sw-chips, .sw.stack .sw-why { margin-top: 22px; }

/* the swarm page */
/* Back: a quiet control above the picture, at least 44 px tall on a phone */
.sw-back { margin: 0 0 14px -10px; color: var(--text-2); }
.sw-back svg { width: 16px; height: 16px; }
.sw-page .st-mine img { background: #0c0c0e; }
.sw-posts { margin: 14px 0 0; padding: 0; list-style: none; max-width: 760px; }
/* a fixed handle column: every line's words end at the same place */
.sw-posts a { display: grid; grid-template-columns: 46px minmax(0, 1fr) minmax(0, 220px); gap: 14px; align-items: baseline; padding: 10px 0; color: var(--text); text-decoration: none; border-bottom: 1px dashed var(--line); }
.sw-posts a:hover .sw-t { text-decoration: underline; text-decoration-color: var(--line-3); text-underline-offset: 3px; }
.sw-posts time { font: 500 12px/1.3 var(--mono); color: var(--text-3); }
.sw-t { font: 400 14.5px/1.4 var(--sans); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sw-h { max-width: 220px; font: 400 12px/1.3 var(--mono); color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sw-t + .sw-h { justify-self: end; }
.sw-more { max-width: 760px; }
.sw-more summary { padding: 12px 0 0; cursor: pointer; list-style: none; font: 500 12px/1.3 var(--mono); color: var(--text-3); }
.sw-more summary::-webkit-details-marker { display: none; }
.sw-more summary:hover { color: var(--text); }
.sw-more[open] summary { display: none; }
.sw-more .sw-posts { margin: 0; }

/* home: the wall peeks in at the bottom of the first screen (heading and the top of the first row,
   placed by placeWall in ui/swarm.ts) and scrolls up over the painting. The credit is lifted with a
   transform, so the hero and its search box do not move when the wall arrives. */
.home.has-wall .credit { transform: translateY(calc(-1 * var(--sw-lift, 0px))); }
.sw-wall { position: absolute; top: calc(100% - 52px); left: 0; right: 0; z-index: 3; padding: 14px 0 48px; background: linear-gradient(rgba(0, 0, 0, 0), rgba(5, 5, 6, 0.94) 52px); animation: fade 0.6s 0.9s both; }
.sw-wall > * { width: min(980px, calc(100% - 32px)); margin-left: auto; margin-right: auto; }
.sw-wall h2 { margin-top: 0; margin-bottom: 0; font: 600 21px/1.2 var(--sans); letter-spacing: -0.01em; color: #fff; text-shadow: 0 2px 12px #000; }
.sw-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; margin-top: 36px; }
.sw-tile { position: relative; display: block; aspect-ratio: 1; overflow: hidden; background: #0c0c0e; border: 1px solid var(--line-2); transition: border-color 0.15s, transform 0.15s; }
.sw-tile:hover, .sw-tile:focus-visible { border-color: var(--text-2); transform: translateY(-2px); outline: none; }
.sw-tile img { display: block; width: 100%; height: 100%; object-fit: cover; }
.sw-tile b { position: absolute; left: 6px; bottom: 6px; min-width: 26px; padding: 4px 6px 3px; font: 600 12px/1 var(--mono); text-align: center; color: var(--black); background: var(--vc); font-variant-numeric: tabular-nums; }

@media (max-width: 860px) {
  .sw-back { height: 44px; margin-bottom: 10px; }
  .sw { grid-template-columns: minmax(0, 1fr); grid-template-areas: "word" "plot" "say"; }
  .sw-plot { margin-top: 18px; }
  .sw-chips { gap: 6px; margin-top: 16px; }
  .sw-chips li { padding: 6px 10px; font-size: 14px; }
  .sw-posts a { grid-template-columns: 42px minmax(0, 1fr); gap: 2px 12px; }
  .sw-h { grid-column: 2; max-width: 100%; }
  .sw-t + .sw-h { justify-self: start; }
  .sw-tiles { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; margin-top: 28px; }
}
@media (prefers-reduced-motion: reduce) {
  .sw-tile { transition: none; }
  .sw-wall { animation: none; }
